const $=s=>document.querySelector(s), today=()=>new Date().toLocaleDateString('sv-SE');
const initial=()=>({checks:{},tasks:[],sessions:[],journals:[],points:0,clean:0,fish:0,timer:null});
let state;try{state=JSON.parse(localStorage.getItem('mindshift-v1'))||initial()}catch{state=initial()}
let page='today', mood=state.checks[today()]?.mood||3, breathing=false;
const esc=s=>String(s).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function save(){try{localStorage.setItem('mindshift-v1',JSON.stringify(state))}catch{toast('Tarayıcı kayıt alanı kullanılamıyor. Verilerin kalıcı kaydedilemedi.')}}
function toast(s){$('#toast').textContent=s;$('#toast').style.display='block';clearTimeout(window.toastId);window.toastId=setTimeout(()=>$('#toast').style.display='none',3500)}
const moods=['Zorlanıyorum','Biraz düşük','Dengeliyim','İyiyim','Çok iyiyim'], faces=['😔','😕','😐','🙂','😊'];
function recommendation(){const c=state.checks[today()];return !c?{minutes:25,rest:5,text:'Günlük durumunu kaydederek planını kendine uyarla.'}:c.mood<=2||c.energy<=2?{minutes:15,rest:5,text:'Bugün küçük adımlarla ilerleyelim. 15 dakikalık çalışma ve 5 dakikalık mola öneriyoruz.'}:c.mood>=4&&c.energy>=4?{minutes:40,rest:10,text:'Enerjin yüksek. 40 dakikalık çalışma blokları arasına 10 dakikalık molalar ekleyebilirsin.'}:{minutes:25,rest:5,text:'Dengeli bir ritim: 25 dakika çalışma, ardından 5 dakika mola.'}}
function pond(){return `<div class="pond" aria-label="Gölet temizliği yüzde ${state.clean}, ${state.fish} balık"><div class="water" style="filter:saturate(${.35+state.clean/100})"><span class="leaf">❧</span>${Array.from({length:state.fish},(_,i)=>`<span class="fish" style="left:${18+(i*17)%55}%;top:${20+(i*23)%45}%;animation-delay:-${i}s">${i%2?'🐟':'🐠'}</span>`).join('')}</div></div>`}
function title(label,heading,desc){return `<div class="heading"><div class="label">${label}</div><h1>${heading}</h1><p>${desc}</p></div>`}
function tasks(){const list=state.tasks.filter(t=>t.date===today());return list.length?list.map(t=>`<div class="row task ${t.done?'done':''}"><div><h3>${esc(t.name)}</h3><p>${t.minutes} dk çalışma · ${t.rest} dk mola</p></div><button class="secondary" data-complete="${t.id}" ${t.done?'disabled':''}>${t.done?'✓ Tamamlandı':'Tamamla +20'}</button></div>`).join(''):'<div class="empty"><p>Bugün için henüz bir planın yok.</p><button class="secondary" data-go="plan">İlk çalışma hedefini ekle ↗</button></div>'}
function timer(){return `<div class="card timer"><div class="label">BİR ŞEYE ODAKLAN</div><h2>Kendine bu zamanı ayır.</h2><select id="duration" aria-label="Odak süresi" ${state.timer?'disabled':''}>${[15,25,40].map(n=>`<option value="${n}" ${n===(state.timer?.minutes||recommendation().minutes)?'selected':''}>${n} dakika</option>`).join('')}</select><div class="clock" id="clock">25:00</div><div class="actions" style="justify-content:center"><button class="primary" id="timer-toggle">${state.timer?.end?'Duraklat':state.timer?'Devam et':'Odaklanmaya başla'}</button><button class="secondary" id="timer-reset">Sıfırla</button></div><p class="subtle" style="margin:20px 0 0">Tamamlanan her odak seansı +10 puan.</p></div>`}
function render(){document.querySelectorAll('nav button').forEach(b=>b.classList.toggle('active',b.dataset.page===page));const r=recommendation();const c=state.checks[today()];let html='';
if(page==='today') html=title('SENİN ALANIN','Bugün, kendine iyi bir başlangıç yap.','Her gün aynı hissetmek zorunda değilsin. Birlikte bugünün ritmini bulalım.')+`<div class="grid"><div><section class="card"><div class="label">GÜNLÜK KONTROL</div><h2>Bugün nasıl hissediyorsun?</h2><p>Planını sana uydurmak için küçük bir mola.</p><div class="moods">${faces.map((f,i)=>`<button data-mood="${i+1}" aria-pressed="${mood===i+1}" class="${mood===i+1?'selected':''}">${f}<small>${moods[i]}</small></button>`).join('')}</div><label for="energy">Çalışma motivasyonun <span id="energy-value">${c?.energy||3}</span>/5</label><input id="energy" type="range" min="1" max="5" value="${c?.energy||3}"><label for="note">Aklından geçenler <span class="subtle">(isteğe bağlı)</span></label><textarea id="note" maxlength="2000" placeholder="Bugün beni düşündüren şey…">${esc(c?.note||'')}</textarea><button class="primary full" id="check-save">${c?'Kaydı güncelle':'Durumumu kaydet'} →</button></section><section class="card"><div class="row"><h2>Bugünün küçük adımları</h2><button class="secondary" data-go="plan">Planım ↗</button></div>${tasks()}</section></div><div><section class="card"><div class="row"><div><div class="label">KÜÇÜK ADIMLARIN HAYAT BULUYOR</div><h2>Senin göletin</h2></div><span class="badge">${state.points} puan</span></div>${pond()}<p class="pond-caption">Her tamamlanan hedefle biraz daha canlı.</p><button class="secondary full" data-go="pond">Göletime git ↗</button></section><section class="card" style="background:#edf1e5"><div class="label">BUGÜNÜN RİTMİ</div><h2>${r.minutes} dakika ile başla.</h2><p>${r.text}</p><button class="secondary" data-go="plan">Çalışmaya geç →</button></section></div></div>`;
if(page==='plan')html=title('AKADEMİK PLANLAMA','Büyük hedefler, küçük adımlar.','Bugünkü enerjine göre bir çalışma hedefi belirle.')+`<div class="grid"><div><section class="card"><h2>Yeni bir çalışma hedefi</h2><p>${r.text}</p><form id="task-form"><label for="task-name">Ders veya küçük hedef</label><input id="task-name" required maxlength="120" placeholder="Örn. Matematik · 10 türev sorusu"><button class="primary full">Planıma ekle</button></form><div class="hint">Öneriler günlük ruh hali ve motivasyon puanına göre basit kurallarla hazırlanır. Yeni kayıt, bundan sonra eklediğin blokları etkiler.</div></section><section class="card"><h2>Bugünkü planım</h2>${tasks()}</section></div>${timer()}</div>`;
if(page==='pond')html=title('KİŞİSEL EKOSİSTEMİN','İlerlemen burada hayat buluyor.','Çalışma hedeflerini tamamla, puan kazan ve göletine yaşam kat.')+`<div class="grid"><section class="card">${pond()}<div class="row"><h2>Göletinin berraklığı</h2><b>%${state.clean}</b></div><div class="progress"><span style="width:${state.clean}%"></span></div><p>${state.fish} balık göletinde yüzüyor.</p></section><section class="card"><div class="label">KULLANILABİLİR PUAN</div><h1>${state.points}</h1><div class="task"><h2>Suyu berraklaştır</h2><p>20 puan karşılığında göletini %20 temizle.</p><button class="primary" id="clean" ${state.points<20||state.clean>=100?'disabled':''}>${state.clean>=100?'Göletin tamamen temiz':'Temizle · 20 puan'}</button></div><div class="task"><h2>Yeni bir balık ekle</h2><p>Göletine yeni bir dost. En fazla 8 balık.</p><button class="primary" id="fish" ${state.points<40||state.fish>=8?'disabled':''}>Balık ekle · 40 puan</button></div><div class="hint">Çalışma hedefi: +20 puan<br>Odak seansı: +10 puan</div></section></div>`;
if(page==='wellbeing')html=title('KENDİNE ALAN AÇ','Biraz durmak da ilerlemenin parçası.','Düşüncelerine yer açabileceğin sakin bir köşe.')+`<div class="grid"><section class="card"><div class="label">FARKINDALIK MOLASI</div><h2>Bir dakikalığına yavaşla.</h2><p>İstersen animasyonu izlerken rahat bir ritimde nefes alıp ver. Rahatsız hissedersen durabilirsin.</p><div class="breath ${breathing?'breathing':''}" id="breath">${breathing?'Kendi ritminde':'Hazır olduğunda'}</div><button class="secondary full" id="breath-toggle">${breathing?'Bitir':'Molayı başlat'}</button></section><section class="card"><div class="label">DÜŞÜNCE GÜNLÜĞÜ</div><h2>Kendine başka bir açıdan bak.</h2><form id="journal-form"><label for="thought">Aklımdan geçen düşünce</label><textarea id="thought" required maxlength="2000" placeholder="Bu sınava yetişemeyeceğim…"></textarea><label for="alternative">Daha dengeli bir bakış</label><textarea id="alternative" required maxlength="2000" placeholder="Hepsini bugün bitirmem gerekmiyor. Bir konuyla başlayabilirim."></textarea><button class="primary full">Günlüğüme kaydet</button></form><p class="subtle" style="margin:15px 0 0">Bu alan kişisel düşünme içindir; klinik değerlendirme veya terapi içermez.</p></section></div>`;
if(page==='history')html=title('KENDİ RİTMİNDE İLERLE','Küçük adımlarının izleri.','Kayıtlarını ve tamamladığın çalışmaları burada görebilirsin.')+`<div class="stats"><div class="stat"><b>${state.tasks.filter(t=>t.done).length}</b><span>Tamamlanan hedef</span></div><div class="stat"><b>${state.sessions.reduce((s,t)=>s+t.minutes,0)} dk</b><span>Toplam odak süresi</span></div><div class="stat"><b>${Object.keys(state.checks).length}</b><span>Günlük durum kaydı</span></div></div><div class="grid"><section class="card"><h2>Günlük durumlarım</h2>${Object.entries(state.checks).sort((a,b)=>b[0].localeCompare(a[0])).map(([d,c])=>`<div class="history-row"><h3>${esc(d)} · ${faces[c.mood-1]} ${moods[c.mood-1]}</h3><p>Motivasyon: ${c.energy}/5<br>${esc(c.note)}</p></div>`).join('')||'<p>İlk günlük kaydını Bugün ekranından ekle.</p>'}</section><section class="card"><h2>Düşünce günlüğüm</h2>${state.journals.slice().reverse().map(j=>`<div class="history-row"><div class="label">${esc(j.date)}</div><p>${esc(j.thought)}</p><h3>Daha dengeli bir bakış</h3><p>${esc(j.alternative)}</p></div>`).join('')||'<p>Kaydettiğin düşünceler burada görünecek.</p>'}<button class="secondary" id="export">Verilerimi indir</button></section></div>`;
$('#view').innerHTML=html;bind();updateClock();}
function bind(){document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>navigate(b.dataset.go));document.querySelectorAll('[data-mood]').forEach(b=>b.onclick=()=>{mood=+b.dataset.mood;document.querySelectorAll('[data-mood]').forEach(x=>{x.classList.toggle('selected',x===b);x.setAttribute('aria-pressed',x===b)})});if($('#energy'))$('#energy').oninput=e=>$('#energy-value').textContent=e.target.value;
if($('#check-save'))$('#check-save').onclick=()=>{state.checks[today()]={mood,energy:+$('#energy').value,note:$('#note').value};save();render();toast('Günlük durumun kaydedildi. Plan önerin güncellendi.')};
if($('#task-form'))$('#task-form').onsubmit=e=>{e.preventDefault();const name=$('#task-name').value.trim();if(!name)return;state.tasks.push({id:crypto.randomUUID(),name,date:today(),minutes:recommendation().minutes,rest:recommendation().rest,done:false});save();render();toast('Çalışma hedefin eklendi.')};
document.querySelectorAll('[data-complete]').forEach(b=>b.onclick=()=>{const t=state.tasks.find(t=>t.id===b.dataset.complete);if(t&&!t.done){t.done=true;state.points+=20;save();render();toast('Bir adım daha! Göletin için +20 puan.')}});
if($('#timer-toggle'))$('#timer-toggle').onclick=()=>{if(!state.timer)state.timer={minutes:+$('#duration').value,remaining:+$('#duration').value*60,end:0};if(state.timer.end){state.timer.remaining=Math.max(0,Math.ceil((state.timer.end-Date.now())/1000));state.timer.end=0}else state.timer.end=Date.now()+state.timer.remaining*1000;save();render()};if($('#timer-reset'))$('#timer-reset').onclick=()=>{state.timer=null;save();render()};if($('#duration'))$('#duration').onchange=updateClock;
if($('#clean'))$('#clean').onclick=()=>{if(state.points>=20&&state.clean<100){state.points-=20;state.clean+=20;save();render();toast('Göletin biraz daha berrak!')}};if($('#fish'))$('#fish').onclick=()=>{if(state.points>=40&&state.fish<8){state.points-=40;state.fish++;save();render();toast('Göletine yeni bir dost katıldı.')}};
if($('#breath-toggle'))$('#breath-toggle').onclick=()=>{breathing=!breathing;render()};if($('#journal-form'))$('#journal-form').onsubmit=e=>{e.preventDefault();const thought=$('#thought').value.trim(),alternative=$('#alternative').value.trim();if(!thought||!alternative)return;state.journals.push({date:today(),thought,alternative});save();render();toast('Düşüncelerin günlüğüne kaydedildi.')};
if($('#export'))$('#export').onclick=()=>{const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([JSON.stringify(state,null,2)],{type:'application/json'}));a.download='mindshift-verilerim.json';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};}
function updateClock(){let sec=state.timer?(state.timer.end?Math.max(0,Math.ceil((state.timer.end-Date.now())/1000)):state.timer.remaining):(Number($('#duration')?.value)||25)*60;if(state.timer?.end&&sec===0){state.sessions.push({date:today(),minutes:state.timer.minutes});state.points+=10;state.timer=null;save();render();toast('Odak seansın tamamlandı! +10 puan. Şimdi mola zamanı.');return}if($('#clock'))$('#clock').textContent=`${Math.floor(sec/60).toString().padStart(2,'0')}:${(sec%60).toString().padStart(2,'0')}`;}
function navigate(p){page=['today','plan','pond','wellbeing','history'].includes(p)?p:'today';location.hash=page;render()}
document.querySelectorAll('nav button').forEach(b=>b.onclick=()=>navigate(b.dataset.page));window.addEventListener('hashchange',()=>navigate(location.hash.slice(1)));$('#date').textContent=new Date().toLocaleDateString('tr-TR',{day:'numeric',month:'long',weekday:'long'});navigate(location.hash.slice(1));setInterval(updateClock,500);
